import React, { useState } from 'react';
import './Admin.css';

const ForumForm = ({ onSubmit }) => {
    const [name, setName] = useState('');
    const [description, setDescription] = useState('');
    const [categoryId, setCategoryId] = useState('');
    const [banner, setBanner] = useState('');
    const [error, setError] = useState(null);
    const [success, setSuccess] = useState(null);

    const handleSubmit = (e) => {
        e.preventDefault();

        if (!name || !description || !categoryId) {
            setError("All fields are required.");
            return;
        }

        onSubmit({ name, description, category_id: categoryId, banner })
            .then(() => {
                setSuccess("Forum created successfully!");
                setName('');
                setDescription('');
                setCategoryId('');
                setBanner('');
                setError(null);
            })
            .catch((err) => {
                setError("An error occurred while creating the forum.");
                setSuccess(null);
            });
    };

    return (
        <form onSubmit={handleSubmit} className="admin-panel-form">
            <h2>Create a New Forum</h2>

            {error && <div className="error-message">{error}</div>}
            {success && <div className="success-message">{success}</div>}

            <label>
                Name:
                <input 
                    type="text" 
                    value={name} 
                    onChange={(e) => setName(e.target.value)} 
                    required 
                />
            </label>

            <label>
                Description:
                <textarea 
                    value={description} 
                    onChange={(e) => setDescription(e.target.value)} 
                    required 
                />
            </label>

            <label>
                Category ID:
                <input 
                    type="text" 
                    value={categoryId} 
                    onChange={(e) => setCategoryId(e.target.value)} 
                    required 
                />
            </label>

            <label>
                Banner URL:
                <input 
                    type="text" 
                    value={banner} 
                    onChange={(e) => setBanner(e.target.value)} 
                />
            </label>

            <button type="submit">Create Forum</button>
        </form>
    );
};

export default ForumForm;
